int* largestDivisibleSubset(int* nums, int numsSize, int* returnSize) {
    if (numsSize == 0) { *returnSize = 0; return NULL; }
    // Bubble or qsort nums
    for (int i = 0; i < numsSize - 1; i++) {
        for (int j = 0; j < numsSize - i - 1; j++) {
            if (nums[j] > nums[j + 1]) { int t = nums[j]; nums[j] = nums[j + 1]; nums[j + 1] = t; }
        }
    }
    int* dp = (int*)malloc(numsSize * sizeof(int));
    int* parent = (int*)malloc(numsSize * sizeof(int));
    for (int i = 0; i < numsSize; i++) { dp[i] = 1; parent[i] = -1; }
    int max_idx = 0;
    for (int i = 0; i < numsSize; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] % nums[j] == 0 && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
                parent[i] = j;
            }
        }
        if (dp[i] > dp[max_idx]) max_idx = i;
    }
    *returnSize = dp[max_idx];
    int* res = (int*)malloc(dp[max_idx] * sizeof(int));
    int curr = max_idx, idx = dp[max_idx] - 1;
    while (curr != -1) {
        res[idx--] = nums[curr];
        curr = parent[curr];
    }
    free(dp); free(parent);
    return res;
}

